python3 - <<'PY'
import zipfile,xml.etree.ElementTree as E,glob
for p in glob.glob('docs/kiertokirjeet/*')+glob.glob('docs/liitteet/*'):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  for n in z.namelist():
   if n=='word/document.xml' or n=='xl/sharedStrings.xml' or n.startswith('xl/worksheets/sheet') and n.endswith('.xml'):
    root=E.fromstring(z.read(n))
    print(n)
    if n=='word/document.xml':
     ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
     for para in root.findall('.//w:p',ns): print(''.join(para.itertext()))
    else: print(E.tostring(root,encoding='unicode'))
PY"

